import pytest

from bedrock_protocol import v1001, v2168, v2225

# TODO: confirm against BDS: gophertunnel flattens AgentCapabilities to a lone Optional[bool] and writes one
# presence byte; serialize<EducationLevelSettings>::write in 1.26.40 writes the optional<AgentCapabilities> marker
# before the optional<bool> member's own, so gophertunnel has to give.
# generated by gophertunnel b8bd735:
# &packet.EducationSettings{CodeBuilderDefaultURI: "https://code.builder/", CodeBuilderTitle: "Code Builder",
# CanResizeCodeBuilder: true, DisableLegacyTitleBar: false, PostProcessFilter: "sepia",
# ScreenshotBorderPath: "textures/ui/edu_border", CanModifyBlocks: protocol.Option(true),
# OverrideURI: protocol.Option("https://override/"), HasQuiz: false,
# ExternalLinkSettings: protocol.Option(protocol.EducationExternalLinkSettings{URL: "https://link/",
# DisplayName: "Link"})}
FULL = bytes.fromhex(
    "1568747470733a2f2f636f64652e6275696c6465722f0c436f6465204275696c64657201000573657069611674657874757265732f75692f6564755f626f72646572"
    "01"  # TODO: patched, confirm against BDS
    "0101011168747470733a2f2f6f766572726964652f00010d68747470733a2f2f6c696e6b2f044c696e6b"
)

# generated by gophertunnel b8bd735:
# &packet.EducationSettings{}
UNSET = bytes.fromhex("00000000000000000000")

FULL_PACKET = v2225.EducationSettingsPacket(
    education_level_settings=v2225.EducationLevelSettings(
        code_builder_default_uri="https://code.builder/",
        code_builder_title="Code Builder",
        can_resize_code_builder=True,
        disable_legacy_title_bar=False,
        post_process_filter="sepia",
        screenshot_border_resource_path="textures/ui/edu_border",
        agent_capabilities=v2225.AgentCapabilities(can_modify_blocks=True),
        local_settings=v2225.EducationLocalLevelSettings(code_builder_override_uri="https://override/"),
        external_link_settings=v2225.ExternalLinkSettings(url="https://link/", display_name="Link"),
    )
)

UNSET_PACKET = v2225.EducationSettingsPacket()

AGENT_CAPABILITIES_ONLY = v2225.EducationSettingsPacket(
    education_level_settings=v2225.EducationLevelSettings(agent_capabilities=v2225.AgentCapabilities())
)

GOLDENS = [
    pytest.param(FULL_PACKET, FULL, id="full"),
    pytest.param(UNSET_PACKET, UNSET, id="unset"),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225], ids=lambda version: version.__name__.rpartition(".")[2])
def test_education_settings_is_packet_137(version):
    assert version.PACKETS[137] is version.EducationSettingsPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_education_settings_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_education_settings_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_education_settings_rejects_the_deprecated_flag_when_set():
    with pytest.raises(ValueError, match="at byte"):
        v2225.EducationSettingsPacket.from_bytes(UNSET[:8] + b"\x01" + UNSET[9:])


def test_agent_capabilities_carry_a_presence_byte_ahead_of_the_can_modify_blocks_flag():
    wire = bytes(AGENT_CAPABILITIES_ONLY)
    assert len(wire) == len(UNSET) + 1
    assert wire[:6] == UNSET[:6]
    assert wire[8:] == UNSET[7:]


def test_agent_capabilities_without_can_modify_blocks_round_trip():
    assert v2225.EducationSettingsPacket.from_bytes(bytes(AGENT_CAPABILITIES_ONLY)) == AGENT_CAPABILITIES_ONLY
